  "heal_target_selection_code": {
    "rule": "Eligible allies are deployed, inside the healer's effective range, and hp + epsilon < max_hp. The healer selects minimum hp/max_hp, tie-broken by operator_id. There is no manual target-selection action.",
    "rule_lines": [
      550,
      553,
      555,
      559
    ],
    "rule_source_excerpt": "    def _target_ally_for(self, state: SimulationState, operator: RuntimeOperator) -> RuntimeOperator | None:\n        covered = self.range_transformer.covered_tiles(origin=operator.tile, offsets=self._effective_range(operator), direction=operator.direction)\n        targets = [ally for ally in state.deployed_operators.values() if ally.hp + self._EPSILON < ally.max_hp and ally.tile in covered]\n        return min(targets, key=lambda ally: (ally.hp / ally.max_hp, ally.operator_id)) if targets else None\n\n    def _heal(self, state: SimulationState, operator: RuntimeOperator, target: RuntimeOperator) -> None:\n        raw_amount = max(1.0, self._effective_atk(operator))\n        actual_amount = min(raw_amount, target.max_hp - target.hp)\n        target.hp += actual_amount\n        self._emit(state, EventType.HEAL, source=operator.operator_id, target=target.operator_id, amount=actual_amount)",
